from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != background]
    source = max(colors, key=lambda c: sum(x == c for row in grid for x in row))
    paint = next(c for c in colors if c != source)
    out = [row[:] for row in grid]
    border = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == source and (r in (0, h - 1) or c in (0, w - 1))}
    segments = []
    while border:
        seed = min(border)
        border.remove(seed)
        component = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for point in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if point in border:
                    border.remove(point)
                    component.add(point)
                    stack.append(point)
        side_counts = [sum(r == 0 for r, c in component),
                       sum(r == h - 1 for r, c in component),
                       sum(c == 0 for r, c in component),
                       sum(c == w - 1 for r, c in component)]
        side = max(range(4), key=lambda i: side_counts[i])
        if not side_counts[side]:
            continue
        if side == 0:
            coords = sorted(c for r, c in component if r == 0)
            start, dr, dc, axis = (0, coords[0]), 1, 0, 1
        elif side == 1:
            coords = sorted(c for r, c in component if r == h - 1)
            start, dr, dc, axis = (h - 1, coords[0]), -1, 0, 1
        elif side == 2:
            coords = sorted(r for r, c in component if c == 0)
            start, dr, dc, axis = (coords[0], 0), 0, 1, 0
        else:
            coords = sorted(r for r, c in component if c == w - 1)
            start, dr, dc, axis = (coords[0], w - 1), 0, -1, 0
        segments.append((axis, coords, start, dr, dc))
    offsets = {0: set(), 1: set()}
    for axis in (0, 1):
        for segment_axis, coords, start, dr, dc in segments:
            if segment_axis != axis:
                continue
            lo, hi = coords[0], coords[-1]
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == paint:
                        position = r if axis == 0 else c
                        if lo <= position <= hi:
                            offsets[axis].add(position - lo)
        if not offsets[axis]:
            offsets[axis].add(0)
    for axis, coords, start, dr, dc in segments:
        for offset in sorted(offsets[axis]):
            if offset >= len(coords):
                continue
            r, c = start
            if axis == 0:
                r = coords[0] + offset
            else:
                c = coords[0] + offset
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == paint:
                    out[rr][cc] = 4
                    break
                if grid[rr][cc] == background:
                    out[rr][cc] = paint
                rr += dr
                cc += dc
    if h > 1 and w > 1 and grid[0][0] == source and grid[1][0] == source:
        out[1][0] = background
    return out
